package com.aadil.ecommerce.controllers;import com.aadil.ecommerce.dtos.UserResponseDTO;import com.aadil.ecommerce.enums.UserSortDirection;import com.aadil.ecommerce.enums.UserSortField;import com.aadil.ecommerce.responses.APIResponse;import com.aadil.ecommerce.responses.PaginatedResponse;import com.aadil.ecommerce.services.UserService;import lombok.RequiredArgsConstructor;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.GetMapping;import org.springframework.web.bind.annotation.RequestMapping;import org.springframework.web.bind.annotation.RequestParam;import org.springframework.web.bind.annotation.RestController;import java.time.LocalDateTime;import java.util.List;@RestController@RequestMapping("/api/users")@RequiredArgsConstructor@Validatedpublic class UserController {    private final UserService userService;    @GetMapping("/all")    public ResponseEntity<APIResponse<PaginatedResponse<List<UserResponseDTO>>>> getAllUsers        (@RequestParam(required = false,name = "Search") String search,         @RequestParam (required = false, name = "PageNumber",defaultValue = "0") int pageNumber,         @RequestParam (required = false,name = "Size",defaultValue = "10") int size,         @RequestParam (required = false,name = "SortField",defaultValue = "ID") UserSortField userSortField,         @RequestParam (required = false,name = "SortDirection",defaultValue = "ASC") UserSortDirection sortDirection) {        PaginatedResponse<List<UserResponseDTO>> contents = userService.getAllUsers(search,pageNumber,size,userSortField,sortDirection);        APIResponse<PaginatedResponse<List<UserResponseDTO>>> apiResponse = new APIResponse<>();        apiResponse.setSuccess(true);        apiResponse.setCode(200);        apiResponse.setMessage("All Users retrieved successfully");        apiResponse.setData(contents);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse, HttpStatus.OK);    }}